<?php require_once __DIR__.'/../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$lead=(int)$_POST['lead_id'];$title=clean_text($_POST['title']??'',160);$amount=(float)$_POST['amount'];$currency=clean_text($_POST['currency']??'USD',8);$notes=clean_text($_POST['notes']??'',2000);$s=db()->prepare('SELECT customer_id FROM leads WHERE id=?');$s->execute([$lead]);$cid=$s->fetchColumn();$code='QUO-'.strtoupper(bin2hex(random_bytes(4)));$s=db()->prepare('INSERT INTO quotes(quote_code,lead_id,customer_id,title,amount,currency,notes,status) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$code,$lead,$cid?:null,$title,$amount,$currency,$notes,'Sent']);header('Location:quotes.php');exit;}$leads=db()->query("SELECT id,lead_code,name,business FROM leads WHERE status IN ('New','Contacted') ORDER BY created_at DESC")->fetchAll();$quotes=db()->query('SELECT q.*,l.lead_code,l.business FROM quotes q LEFT JOIN leads l ON l.id=q.lead_id ORDER BY q.created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quotes | CRM</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">W</span><span>Web<span>Studio</span></span></a><nav class="nav"><a href="index.php">CRM</a><a href="customers.php">Customers</a><a href="projects.php">Projects</a><a href="logout.php">Log out</a></nav></header><main><section class="section"><span class="eyebrow">SALES</span><h1>Quotes</h1><div class="card-3d" style="padding:26px;border-radius:24px;max-width:850px"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><div class="form-grid"><div class="field"><label>Lead</label><select name="lead_id" required><?php foreach($leads as $l):?><option value="<?=$l['id']?>"><?=htmlspecialchars($l['lead_code'].' — '.$l['business'])?></option><?php endforeach;?></select></div><div class="field"><label>Title</label><input name="title" required placeholder="Website Development"></div><div class="field"><label>Amount</label><input name="amount" type="number" step="0.01" required></div><div class="field"><label>Currency</label><select name="currency"><option>USD</option><option>EUR</option><option>AUD</option><option>INR</option><option>GBP</option></select></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div><div class="field full"><button class="btn btn-3d">Create Quote →</button></div></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Quote</th><th>Business</th><th>Title</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($quotes as $q):?><tr><td><?=htmlspecialchars($q['quote_code'])?></td><td><?=htmlspecialchars($q['business']??'')?></td><td><?=htmlspecialchars($q['title'])?></td><td><?=htmlspecialchars($q['currency'].' '.$q['amount'])?></td><td><span class="status"><?=htmlspecialchars($q['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>